// ═══════════════════════════════════════════════════════════════════════
// Build Cache — Agrupa asesores por sucursal, calcula primarios vs multi
// y overflow. Formato listo para consumir por SUB · Auto-Asignar Asesor.
// ═══════════════════════════════════════════════════════════════════════

function F(r){ return (r && r.fields && typeof r.fields === 'object') ? r.fields : (r || {}); }

// ── Traer datos crudos ──
const asesoresRaw = $('Airtable · Get Asesores').all().map(i => ({ id: i.json.id, ...F(i.json) }));
const sucursalesRaw = $('Airtable · Get Sucursales').all().map(i => ({ id: i.json.id, ...F(i.json) }));

// ── Mapa sucursal_rec → info sucursal ──
const sucursalPorRec = {};
const sucursalPorCodigo = {};
sucursalesRaw.forEach(s => {
  const info = {
    sucursal_rec: s.id,
    sucursal_id: s.sucursal_id || '',
    sucursal_nombre: s.nombre || s.sucursal_id || '',
    sucursal_direccion: s.direccion || '',
    sucursal_ciudad: s.ciudad || ''
  };
  sucursalPorRec[s.id] = info;
  if (s.sucursal_id) sucursalPorCodigo[s.sucursal_id] = info;
});

// ── Filtrar asesores DISPONIBLES (los admin/dueños quedan fuera por default) ──
const asesoresDisponibles = asesoresRaw.filter(a => a.disponible === true);

// ── Clasificar cada asesor: PRIMARIO (1 sucursal) vs MULTI (2+) ──
function normalizarAsesor(a) {
  const sucsLink = Array.isArray(a.sucursal) ? a.sucursal : [];
  return {
    asesor_rec: a.id,
    asesor_id: a.asesor_id || '',
    nombre: (a.nombre || '').trim() || 'Asesor',
    email: a.email || '',
    slack_id: (a.slack_id || '').trim(),
    chatwoot_agent_id: (a.chatwoot_agent_id != null && a.chatwoot_agent_id !== '') ? Number(a.chatwoot_agent_id) : null,
    porcentaje: (a.Porcentaje_leads != null && a.Porcentaje_leads !== '') ? Number(a.Porcentaje_leads) : 0,
    max_leads: Number(a.max_leads_simultaneos) || 9999,
    sucursales_recs: sucsLink,
    disponible: !!a.disponible
  };
}

const asesoresNorm = asesoresDisponibles.map(normalizarAsesor);

// ── Estructura final: por sucursal (usando codigo como key) ──
const porSucursal = {};

// Inicializar cada sucursal con estructura base
sucursalesRaw.forEach(s => {
  if (!s.sucursal_id) return;
  porSucursal[s.sucursal_id] = {
    ...sucursalPorRec[s.id],
    primarios: [],
    multi_sucursal: [],
    suma_porcentajes_primarios: 0,
    overflow_pct: 0
  };
});

// Distribuir asesores en cada sucursal
asesoresNorm.forEach(a => {
  const numSucs = a.sucursales_recs.length;
  if (numSucs === 0) return;

  const esMulti = numSucs >= 2;

  a.sucursales_recs.forEach(sucRec => {
    const sucInfo = sucursalPorRec[sucRec];
    if (!sucInfo) return;
    const sucKey = sucInfo.sucursal_id;
    if (!porSucursal[sucKey]) return;

    if (esMulti) {
      porSucursal[sucKey].multi_sucursal.push({
        ...a,
        sucursales_totales: a.sucursales_recs.map(r => sucursalPorRec[r]?.sucursal_id).filter(Boolean)
      });
    } else {
      porSucursal[sucKey].primarios.push(a);
    }
  });
});

// Calcular overflow por sucursal
Object.keys(porSucursal).forEach(sucKey => {
  const s = porSucursal[sucKey];
  s.suma_porcentajes_primarios = s.primarios.reduce((sum, a) => sum + (Number(a.porcentaje) || 0), 0);
  s.overflow_pct = Math.max(0, 100 - s.suma_porcentajes_primarios);
});

// ── Índice de asesores por rec (para lookups rápidos) ──
const asesoresPorRec = {};
asesoresNorm.forEach(a => {
  asesoresPorRec[a.asesor_rec] = a;
});

// ── Resumen para el log de Slack ──
const totalPrimarios = asesoresNorm.filter(a => a.sucursales_recs.length === 1).length;
const totalMulti = asesoresNorm.filter(a => a.sucursales_recs.length >= 2).length;
const totalSucursales = Object.keys(porSucursal).length;

const sucSinPrimarios = Object.entries(porSucursal)
  .filter(([_, s]) => s.primarios.length === 0)
  .map(([k]) => k);

const sucOverflowAlto = Object.entries(porSucursal)
  .filter(([_, s]) => s.overflow_pct > 20)
  .map(([k, s]) => `${k}(${s.overflow_pct}%)`);

const cache = {
  actualizado_en: new Date().toISOString(),
  total_asesores_disponibles: asesoresNorm.length,
  total_asesores_primarios: totalPrimarios,
  total_asesores_multi: totalMulti,
  total_sucursales: totalSucursales,
  por_sucursal: porSucursal,
  asesores_por_rec: asesoresPorRec
};

return [{
  json: {
    cache,
    resumen: {
      total_asesores: asesoresNorm.length,
      primarios: totalPrimarios,
      multi_sucursal: totalMulti,
      sucursales: totalSucursales,
      sucursales_sin_primarios: sucSinPrimarios,
      sucursales_overflow_alto: sucOverflowAlto,
      actualizado_en: cache.actualizado_en
    }
  }
}];

